"""Initial program for the suite task; SCiEL evolves the EVOLVE-BLOCK."""
N = 100

# EVOLVE-BLOCK-START
import numpy as np

def construct():
    # We want to minimize the maximum overlap with shifted 1-h.
    # Assuming "overlap" corresponds to autocorrelation or intersection size,
    # we want a sequence with low autocorrelation at non-zero lags.
    # A balanced binary sequence generated by a chaotic map (logistic)
    # or a pseudo-random permutation of 0s and 1s should have near-zero
    # autocorrelation for most lags, which is much lower than the constant
    # sequence (seed).
    
    # Generate a chaotic sequence using the logistic map
    r = 3.999  # Near-chaotic regime
    x = 0.5
    seq = []
    for _ in range(N):
        x = r * x * (1 - x)
        # Threshold to create binary steps 0 and 1
        # Use 0.5 as threshold to ensure roughly balanced
        seq.append(1.0 if x > 0.5 else 0.0)
    
    h = np.array(seq)
    
    # Ensure exactly N/2 ones and N/2 zeros to satisfy sum = N/2
    # The logistic map might not produce exactly 50/50.
    # We will adjust by swapping elements to balance the sum.
    num_ones = np.sum(h)
    target_ones = N / 2
    
    if num_ones < target_ones:
        # Need more ones. Swap zeros to ones.
        zeros_idx = np.where(h == 0)[0]
        needed = int(target_ones - num_ones)
        if needed > 0:
            # Pick random zeros to flip (using fixed seed for reproducibility in this block if needed, 
            # but np.random is fine as long as it's deterministic per run or we use a fixed pattern)
            # To be safe and deterministic without random state issues, we can just pick the first 'needed' zeros.
            # However, random shuffling is better for low correlation.
            # Let's use a simple deterministic shuffle based on index parity or similar?
            # Actually, just flipping the first 'needed' zeros might create structure.
            # Better: Use a fixed random seed for the selection.
            np.random.seed(42)
            indices_to_flip = np.random.choice(zeros_idx, size=needed, replace=False)
            h[indices_to_flip] = 1.0
    elif num_ones > target_ones:
        # Need fewer ones. Swap ones to zeros.
        ones_idx = np.where(h == 1)[0]
        excess = int(num_ones - target_ones)
        if excess > 0:
            np.random.seed(42)
            indices_to_flip = np.random.choice(ones_idx, size=excess, replace=False)
            h[indices_to_flip] = 0.0
            
    return h
# EVOLVE-BLOCK-END
